/* Includes */
#include <errno.h>
#include <stdint.h>

#include "standard_output/serial_io.h"
#include "sysmem_bounds.h"

/**
 * Pointer to the current high watermark of the heap usage
 */
static uint8_t *__sbrk_heap_end = NULL;

/** Largest heap end ever reached, so `osinfo` can report it. Never decreases. */
static uint8_t *__sbrk_heap_peak = NULL;

/**
 * @brief _sbrk() allocates memory to the newlib heap and is used by malloc
 *        and others from the C library
 *
 * @verbatim
 * ##########################################################################
 * # .data # .bss #   newlib heap   #    ThreadX byte pools    # MSP stack  #
 * ##########################################################################
 * ^-- RAM start  ^-- _end          ^-- __RAM_segment_used_end__   _estack --^
 * @endverbatim
 *
 * WHERE THE CEILING IS, AND WHY IT MOVED (finding NX-03)
 *
 * ST's template bounds the heap against `_estack - _Min_Stack_Size`, i.e. the bottom of the
 * MSP stack reservation, on the assumption that the heap and the stack are the only two things
 * growing towards each other. On this firmware they are not: everything above
 * `__RAM_segment_used_end__` is published to ThreadX as `_tx_initialize_unused_memory`, and
 * the CMSIS-RTOS2 wrapper carves BOTH byte pools -- every thread stack, every queue, every
 * control block -- out of it.
 *
 * Measured on the linked image: `_end` = 0x200131F0, `__RAM_segment_used_end__` = 0x20013BF0,
 * and the template's ceiling 0x2003F800. So the heap's window was 181 776 bytes of which only
 * the first 2 560 belonged to it, and the other 179 216 were the byte pools and the RAM above
 * them.
 *
 * AND IT WAS BEING USED. This was not a latent overlap. Capping the heap at the old figure --
 * as a check, before sizing it properly -- wedged the console after seven CLI commands, which
 * is how the real requirement came out: with a deliberately oversized heap the high-water mark
 * settles at 3 600 bytes, appearing when flexPTP starts and not growing afterwards. Every one
 * of those bytes used to come out of the ThreadX byte pools.
 *
 * (The first guess was that `atof()` in the servo and PPS CLI commands was the allocator,
 * since strtod() reaches _Balloc(). The measurement says otherwise: those commands allocate
 * nothing at all with flexPTP stopped. Recorded because the wrong guess is a plausible one.)
 *
 * The linker script drew the line already and said the two allocators were disjoint. They were
 * not, because nothing here consulted it. Now something does, and _Min_Heap_Size is sized from
 * the number above rather than from ST's template.
 *
 * @param incr Memory size
 * @return Pointer to allocated memory
 */
void *_sbrk(ptrdiff_t incr)
{
  extern uint8_t _end; /* Symbol defined in the linker script */
  /* The base of ThreadX's unused-memory region, i.e. the first byte the heap must not touch.
     PROVIDEd by stm32h563zitx_FLASH.ld immediately after the heap/stack reservation. */
  extern uint8_t __RAM_segment_used_end__;
  uint8_t *const max_heap = &__RAM_segment_used_end__;
  uint8_t *prev_heap_end;

  /* Initialize heap end at first call */
  if (NULL == __sbrk_heap_end)
  {
    __sbrk_heap_end = &_end;
    __sbrk_heap_peak = &_end;
  }

  /* Protect the ThreadX byte pools -- and, above them, the MSP stack -- from the heap.
     The arithmetic is in Src/sysmem_bounds.h so that it can be tested without a target; see
     the note there for why five lines earned their own file. */
  uintptr_t next = 0;
  if (!sysmem_bounds_next((uintptr_t)__sbrk_heap_end, (uintptr_t)&_end, (uintptr_t)max_heap,
                          incr, &next))
  {
    /* Report and halt, rather than returning ENOMEM and letting the caller cope.
     *
     * That is a deliberate choice and it is specific to this firmware. The only thing here
     * that allocates is newlib's floating-point conversion machinery -- _Balloc(), reached
     * through strtod() -- and it does NOT tolerate a failure: it takes the NULL and carries
     * on, and what the board actually does is stop responding to the console while everything
     * else keeps running. Measured exactly that way while sizing this heap: seven CLI commands
     * with the window at ST's template 512 bytes, and the CLI thread never spoke again.
     *
     * A board that goes quiet with no explanation is the failure mode this project spends the
     * most effort avoiding (F51, F53, F68). Between a silent wedge and a halt that says what
     * happened and which number to raise, the halt is worth more -- and if a future caller
     * appears that CAN handle ENOMEM, this is the line to reconsider. */
    errno = ENOMEM;

    serial_io_panic_write("\n\n*** FATAL: C heap exhausted\n"
                          "Halted. Raise _Min_Heap_Size in stm32h563zitx_FLASH.ld; `osinfo`\n"
                          "reports the high-water mark against the current size.\n");
    for (;;)
    {
    }
  }

  prev_heap_end = __sbrk_heap_end;
  __sbrk_heap_end = (uint8_t *)next;

  if (__sbrk_heap_end > __sbrk_heap_peak)
  {
    __sbrk_heap_peak = __sbrk_heap_end;
  }

  return (void *)prev_heap_end;
}

/**
 * The C heap, as `osinfo` reports it.
 *
 * Worth having for the reason the byte-pool figures are: the heap is invisible otherwise, and
 * it is now hard-bounded, so "how close is it?" is a question with an answer. It is also the
 * measurement that sized _Min_Heap_Size -- see the note in the linker script.
 */
void sysmem_heap_usage(uint32_t *pPeak, uint32_t *pSize)
{
  extern uint8_t _end;
  extern uint8_t __RAM_segment_used_end__;

  if (pPeak != NULL)
  {
    *pPeak = (__sbrk_heap_peak != NULL) ? (uint32_t)(__sbrk_heap_peak - &_end) : 0U;
  }
  if (pSize != NULL)
  {
    *pSize = (uint32_t)(&__RAM_segment_used_end__ - &_end);
  }
}
